+import {createChatOrchestrator} from './chatOrchestrator.js';
+import type {OrchestratorHooks} from './chatOrchestrator.js';
+import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
+import type {AIProvider, MessageChunk} from '../types/ai.js';
+import type {ChatSession} from '../types/session.js';
+
+interface ObservedRejection {
+  hookCalls: number;
+  hookSessionId: string | undefined;
+  isErrorInstance: boolean;
+  hasOwnCause: boolean;
+  causeMatchesOriginal: boolean;
+  callerReceivedOriginal: boolean;
+}
+
+const failStream = (reason: unknown): Promise<void> => Promise.reject(reason);
+
+const rejectingProvider = (reason: unknown): AIProvider => ({
+  async *sendMessage(): AsyncGenerator<MessageChunk> {
+    await failStream(reason);
+    yield {type: 'stop', stopReason: 'end_turn'};
+  },
+  async generateStructured<T>(): Promise<T> {
+    return {} as T;
+  },
+});
+
+const FIXED_TIMESTAMP = '2026-01-01T00:00:00.000Z';
+const RESOLVE_SENTINEL = Symbol('resolved');
+
+const observeRejection = async (reason: unknown): Promise<ObservedRejection> => {
+  const seen: Array<{sessionId: string; error: Error}> = [];
+  const hooks: OrchestratorHooks = {
+    onError: async (session, error) => {
+      seen.push({sessionId: session.sessionId, error});
+    },
+  };
+  const session: ChatSession = {
+    sessionId: 'session-rejection',
+    userId: 'user-1',
+    entries: [{role: 'user', content: 'ping', timestamp: FIXED_TIMESTAMP}],
+  };
+  const orchestrator = createChatOrchestrator(
+    rejectingProvider(reason),
+    new PromptBuilder({identity: 'Acceptance assistant.'}),
+    undefined,
+    {hooks}
+  );
+  const callerOutcome = await orchestrator
+    .processMessage(session)
+    .then(() => RESOLVE_SENTINEL)
+    .catch((caught: unknown) => caught);
+  const [first] = seen;
+
+  return {
+    hookCalls: seen.length,
+    hookSessionId: first?.sessionId,
+    isErrorInstance: first ? first.error instanceof Error : false,
+    hasOwnCause: first ? 'cause' in first.error : false,
+    causeMatchesOriginal: first ? Object.is(first.error.cause, reason) : false,
+    callerReceivedOriginal: Object.is(callerOutcome, reason),
+  };
+};
+
+describe('ChatOrchestrator onError for non-Error rejections', () => {
+  it('wraps a non-Error rejection in an Error whose cause is the original and still rejects the caller with the original', async () => {
+    const plainRejection = {code: 503, detail: 'gateway unavailable'};
+    const expectedWrapped: ObservedRejection = {
+      hookCalls: 1,
+      hookSessionId: 'session-rejection',
+      isErrorInstance: true,
+      hasOwnCause: true,
+      causeMatchesOriginal: true,
+      callerReceivedOriginal: true,
+    };
+
+    const stringOutcome = await observeRejection('upstream rate limit');
+    const objectOutcome = await observeRejection(plainRejection);
+    const undefinedOutcome = await observeRejection(undefined);
+
+    expect({stringOutcome, objectOutcome, undefinedOutcome}).toEqual({
+      stringOutcome: expectedWrapped,
+      objectOutcome: expectedWrapped,
+      undefinedOutcome: expectedWrapped,
+    });
+  });
+});

